'use server';
/**
 * @fileOverview An AI agent that generates enhancement suggestions and alternative phrasing for a given prompt based on feedback.
 *
 * - generatePromptEnhancementSuggestions - A function that handles the prompt enhancement process.
 * - GeneratePromptEnhancementSuggestionsInput - The input type for the generatePromptEnhancementSuggestions function.
 * - GeneratePromptEnhancementSuggestionsOutput - The return type for the generatePromptEnhancementSuggestions function.
 */

import {ai} from '@/ai/genkit';
import {z} from 'genkit';

const GeneratePromptEnhancementSuggestionsInputSchema = z.object({
  originalPrompt: z.string().describe("The user's original AI prompt."),
  feedback: z
    .string()
    .describe(
      "Structured feedback on the original prompt, highlighting areas for improvement, clarity, and specificity."
    ),
});
export type GeneratePromptEnhancementSuggestionsInput = z.infer<
  typeof GeneratePromptEnhancementSuggestionsInputSchema
>;

const GeneratePromptEnhancementSuggestionsOutputSchema = z.object({
  suggestions: z
    .array(z.string())
    .describe(
      "A list of concrete recommendations to improve the prompt's quality and effectiveness."
    ),
  alternativePhrasing: z
    .array(z.string())
    .describe("A list of alternative phrasings or rewordings for the original prompt."),
});
export type GeneratePromptEnhancementSuggestionsOutput = z.infer<
  typeof GeneratePromptEnhancementSuggestionsOutputSchema
>;

export async function generatePromptEnhancementSuggestions(
  input: GeneratePromptEnhancementSuggestionsInput
): Promise<GeneratePromptEnhancementSuggestionsOutput> {
  return generatePromptEnhancementSuggestionsFlow(input);
}

const prompt = ai.definePrompt({
  name: 'generatePromptEnhancementSuggestionsPrompt',
  input: {schema: GeneratePromptEnhancementSuggestionsInputSchema},
  output: {schema: GeneratePromptEnhancementSuggestionsOutputSchema},
  prompt: `You are an expert AI prompt engineer specializing in refining and improving AI prompts for clarity, specificity, and effectiveness.
Your goal is to provide concrete recommendations and alternative phrasing to enhance a given prompt, based on specific feedback.

Here is the original prompt:
{{{originalPrompt}}}

Here is the feedback and areas for improvement for this prompt:
{{{feedback}}}

Based on the feedback, provide:
1. A list of concrete suggestions to improve the prompt. Each suggestion should be clear and actionable.
2. A list of alternative phrasings or complete rewrites of the original prompt that incorporate the feedback and suggestions. Provide at least 2 distinct alternative phrasings.

Provide your response in JSON format according to the output schema.`,
});

const generatePromptEnhancementSuggestionsFlow = ai.defineFlow(
  {
    name: 'generatePromptEnhancementSuggestionsFlow',
    inputSchema: GeneratePromptEnhancementSuggestionsInputSchema,
    outputSchema: GeneratePromptEnhancementSuggestionsOutputSchema,
  },
  async input => {
    const {output} = await prompt(input);
    return output!;
  }
);
