'use server';

import {
  analyzePromptForFeedback,
  type AnalyzePromptFeedbackOutput,
} from '@/ai/flows/analyze-prompt-for-feedback';
import {
  generatePromptEnhancementSuggestions,
  type GeneratePromptEnhancementSuggestionsOutput,
} from '@/ai/flows/generate-prompt-enhancement-suggestions';
import { z } from 'zod';

const analysisResultSchema = z.object({
  analysis: z.any(), // Using any() for AnalyzePromptFeedbackOutput for simplicity in action
  suggestions: z.any(), // Using any() for GeneratePromptEnhancementSuggestionsOutput
});

export type AnalysisResult = z.infer<typeof analysisResultSchema> & {
  analysis: AnalyzePromptFeedbackOutput;
  suggestions: GeneratePromptEnhancementSuggestionsOutput;
};

export async function getPromptAnalysis(
  prompt: string
): Promise<{ data: AnalysisResult | null; error: string | null }> {
  if (!prompt) {
    return { data: null, error: 'Prompt cannot be empty.' };
  }

  try {
    const analysis = await analyzePromptForFeedback({ promptText: prompt });

    const feedbackString = `Clarity: ${analysis.clarity.feedback}. Specificity: ${analysis.specificity.feedback}. Effectiveness: ${analysis.effectiveness.feedback}. Weaknesses: ${analysis.identifiedWeaknesses.join(', ')}`;

    const suggestions = await generatePromptEnhancementSuggestions({
      originalPrompt: prompt,
      feedback: feedbackString,
    });

    return { data: { analysis, suggestions }, error: null };
  } catch (error) {
    console.error('Error getting prompt analysis:', error);
    return { data: null, error: 'Failed to analyze prompt. Please try again.' };
  }
}
