'use server';
/**
 * @fileOverview An AI agent that analyzes user-submitted prompts for clarity, specificity, and effectiveness.
 *
 * - analyzePromptForFeedback - A function that handles the prompt analysis process.
 * - AnalyzePromptFeedbackInput - The input type for the analyzePromptForFeedback function.
 * - AnalyzePromptFeedbackOutput - The return type for the analyzePromptForFeedback function.
 */

import {ai} from '@/ai/genkit';
import {z} from 'genkit';

const AnalyzePromptFeedbackInputSchema = z.object({
  promptText: z.string().describe('The AI prompt to be analyzed.'),
});
export type AnalyzePromptFeedbackInput = z.infer<
  typeof AnalyzePromptFeedbackInputSchema
>;

const AnalyzePromptFeedbackOutputSchema = z.object({
  overallRating:
    z.number().int().min(1).max(10).describe('An overall rating of the prompt effectiveness from 1 (poor) to 10 (excellent).'),
  clarity: z.object({
    score:
      z.number().int().min(1).max(10).describe('A clarity score from 1 (very unclear) to 10 (exceptionally clear).'),
    feedback: z
      .string()
      .describe(
        'Detailed feedback on the prompt\'s clarity, including suggestions for improvement.'
      ),
  }),
  specificity: z.object({
    score:
      z.number().int().min(1).max(10).describe('A specificity score from 1 (very vague) to 10 (highly specific).'),
    feedback: z
      .string()
      .describe(
        'Detailed feedback on the prompt\'s specificity, including suggestions for improvement.'
      ),
  }),
  effectiveness: z.object({
    score:
      z.number().int().min(1).max(10).describe('An effectiveness score from 1 (ineffective) to 10 (highly effective).'),
    feedback: z
      .string()
      .describe(
        'Detailed feedback on the prompt\'s potential effectiveness, including suggestions for improvement.'
      ),
  }),
  identifiedWeaknesses:
    z.array(z.string()).describe('A list of key weaknesses identified in the prompt.'),
  actionableSuggestions:
    z.array(z.string()).describe('A list of actionable suggestions to improve the prompt.'),
});
export type AnalyzePromptFeedbackOutput = z.infer<
  typeof AnalyzePromptFeedbackOutputSchema
>;

export async function analyzePromptForFeedback(
  input: AnalyzePromptFeedbackInput
): Promise<AnalyzePromptFeedbackOutput> {
  return analyzePromptFeedbackFlow(input);
}

const prompt = ai.definePrompt({
  name: 'analyzePromptFeedbackPrompt',
  input: {schema: AnalyzePromptFeedbackInputSchema},
  output: {schema: AnalyzePromptFeedbackOutputSchema},
  prompt: `You are an expert AI prompt engineer. Your task is to analyze the user's provided AI prompt for its clarity, specificity, and overall effectiveness.
Provide structured, actionable feedback to help the user understand its initial weaknesses and how to improve it.

Rate each aspect (clarity, specificity, effectiveness) on a scale of 1 to 10, where 1 is very poor and 10 is excellent. Also provide detailed feedback and actionable suggestions for each.
Finally, provide an overall rating for the prompt.

The user's AI prompt:
{{{promptText}}}`,
});

const analyzePromptFeedbackFlow = ai.defineFlow(
  {
    name: 'analyzePromptFeedbackFlow',
    inputSchema: AnalyzePromptFeedbackInputSchema,
    outputSchema: AnalyzePromptFeedbackOutputSchema,
  },
  async input => {
    const {output} = await prompt(input);
    return output!;
  }
);
